import type { BChap } from '../types';
const C: BChap[] = [{"v":["Після смерти Ісуса запитували сини Ізраїлеві Господа, говорячи: хто з нас першим піде на хананеян — воювати з ними?","І сказав Господь: Іуда піде; ось, Я віддаю землю в руки його.","Іуда ж сказав Симеону, братові своєму: ввійди зі мною в жереб мій, і будемо воювати з хананеянами; і я ввійду з тобою у твій жереб. І пішов з ним Симеон.","І пішов Іуда, і віддав Господь хананеян і ферезеян у руки їх, і убили вони з них під Везеком десять тисяч чоловік.","У Везеку зустрілися вони з Адоні-Везеком, воювали з ним і розбили хананеян і ферезеян.","Адоні-Везек побіг, але вони погналися за ним і впіймали його і відсікли великі пальці на руках його і на ногах його.","Тоді сказав Адоні-Везек: сімдесят царів з відсіченими на руках і на ногах їхніх великими пальцями збирали [крихти] під столом моїм; як робив я, так і мені відплатив Бог. І привели його в Єрусалим, і він помер там.","І воювали сини Іудині проти Єрусалима і взяли його, й уразили його мечем і місто віддали вогню.","Потім пішли сини Іудині воювати з хананеянами, які жили на горах і на полуденній землі і на низинних місцях.","І пішов Іуда на хананеян, які жили в Хевроні [ім’я ж Хеврону було раніше Кириаф-Арби], і розбив Шешая, Ахимана і Фалмая [з роду Єнакового].","Звідти пішов він проти жителів Давира; ім’я Давира було раніше Кириаф-Сефер.","І сказав Халев: хто розіб’є Кириаф-Сефер і візьме його, тому віддам Ахсу, дочку мою, за дружину.","І взяв його Гофониїл, син Кеназа, молодшого брата Халевового, і Халев віддав за дружину йому Ахсу, дочку свою.","Коли належало їй іти, Гофониїл навчив її просити у батька її поле, і вона зійшла з осла. Халев сказав їй: що тобі?","[Ахса] сказала йому: дай мені благословення; ти дав мені землю полуденну, дай мені і джерела води. І дав їй [Халев за бажанням її] джерела верхні і джерела нижні.","І сини [Іофора] кенеянина, тестя Мойсеєвого, пішли з міста Пальм із синами Іудиними в пустелю Іудину, що на південь від Арада, і прийшли й оселилися серед народу.","І пішов Іуда із Симеоном, братом своїм, і розбили хананеян, які жили в Цефафі, і піддали його закляттю, і тому називається місто це Хорма.","Іуда взяв також Газу з передмістями її, Аскалон з передмістями його, і Екрон з передмістями його [і Азот з околицями його].","Господь був з Іудою, і він оволодів горою; але жителів долини не міг прогнати, тому що в них були залізні колісниці.","І віддали Халеву Хеврон, як говорив Мойсей, [і одержав він там у спадщину три міста синів Єнакових] і вигнав звідти трьох синів Єнакових.","Але ієвусеїв, які жили в Єрусалимі, не вигнали сини Веніамінові, і живуть ієвусеями з синами Веніаміна в Єрусалимі до цього дня.","І сини Йосифа пішли також на Вефиль, і Господь був з ними.","[І зупинилися] й оглядали сини Йосифові Вефиль [ім’я ж місту було раніше Луз].","І побачили вартові чоловіка, який йде з міста, [і взяли його] і сказали йому: покажи нам вхід у місто, і зробимо тобі милість.","Він показав їм вхід у місто, і розбили вони місто мечем, а чоловіка цього і всіх родичів його відпустили.","Чоловік цей пішов у землю хеттеян, і побудував [там] місто і нарік ім’я йому Луз. Це ім’я його по цей день.","І Манассія не вигнав жителів Бефсана [який є Скифополь] і залежних від нього міст, Фаанаха і залежних від нього міст, жителів Дора і залежних від нього міст, жителів Івлеама і залежних від нього міст, жителів Мегиддона і залежних від нього міст; і залишилися хананеяни жити в землі цій.","Коли Ізраїль прийшов у силу, тоді зробив він хананеян данниками, але вигнати не вигнав їх.","І Єфрем не вигнав хананеян, які живуть у Газері; і жили хананеяни серед них у Газері [і платили їм данину].","І Завулон не вигнав жителів Китрона і жителів Наглола, і жили хананеяни серед них і платили їм данину.","І Асир не вигнав жителів Акко [які платили йому данину, і жителів Дора] і жителів Сидона й Ахлава, Ахзива, Хелви, Афека і Рехова.","І жив Асир серед хананеян, жителів землі тієї, бо не вигнав їх.","І Неффалим не вигнав жителів Вефсамиса і жителів Бефанафа і жив серед хананеян, жителів землі тієї; жителі ж Вефсамиса і Бефанафа були його данниками.","І притисли аморреяни синів Данових у горах, бо не давали їм сходити в долину.","І залишилися аморреяни жити на горі Херес [де ведмеді і лисиці], в Аїалоні і Шаалвимі; але рука синів Йосифових подолала [аморреян], і стали вони данниками їх.","Межі аморреян від узвишшя Акравим і від Сели простягалися і далі."],"x":{"1":"3.27.21|6.20.18","2":"0.49.8","3":"4.33.7","4":"8.11.8","6":"9.4.12","7":"2.24.20|50.7.2","8":"5.15.63|5.18.28","10":"5.15.14","11":"5.12.13|5.15.15","12":"5.15.16","13":"12.4.13","14":"5.15.18","15":"0.33.11","16":"8.15.6","17":"4.2.34|3.14.45","18":"11.1.2","19":"5.17.16","20":"3.14.24|5.14.13|5.15.13","21":"5.15.63|5.18.28","22":"5.16.1","23":"0.28.19","25":"5.6.24","26":"5.16.2","27":"5.17.11|5.21.25|8.31.10","29":"5.16.10|5.21.21","31":"5.15.44|5.19.29","34":"6.18.1","35":"5.19.42"}},{"v":["І прийшов ангел Господній з Галгала в Бохим [і у Вефиль до дому Ізраїлевого] і сказав [їм: так говорить Господь]: Я вивів вас з Єгипту і ввів вас у землю, про яку клявся батькам вашим [дати вам], і сказав Я: «не порушу завіту Мого з вами повік;","і ви не вступайте в союз з жителями землі цієї; [богам їх не поклоняйтеся, ідолів їх розбийте,] жертовники їх зруйнуйте». Але ви не послухали голосу Мого. Що ви це зробили?","І тому говорю Я: [не стану вже переселяти людей цих, яких Я хотів вигнати,] не вижену їх від вас, і будуть вони вам петлею, і боги їх будуть для вас сіттю.","Коли ангел Господній сказав слова ці всім синам Ізраїлевим, то народ підняв голосне волання і заплакав.","Від цього і називають те місце Бохим*. Там принесли вони жертву Господу.","Коли Ісус розпустив народ, і пішли сини Ізраїлеві, [кожен у свій дім і] кожен у свій наділ, щоб одержати в спадщину землю,","тоді народ служив Господу в усі дні Ісуса і в усі дні старійшин, життя яких продовжилося після Ісуса і які бачили усі великі діла Господні, які Він зробив Ізраїлю.","Але коли помер Ісус, син Навина, раб Господній, будучи ста десяти років,","і поховали його в межах наділу його у Фамнаф-Сараі, на горі Єфремовій, на північ від гори Гааша;","і коли весь народ той відійшов до батьків своїх, і постав після них інший рід, який не знав Господа і діл Його, які Він чинив Ізраїлю, —","тоді сини Ізраїлеві стали чинити зле перед очима Господа і стали служити Ваалу;","залишили Господа Бога батьків своїх, Який вивів їх із землі Єгипетської, і звернулися до інших богів, богів народів, які оточували їх, і стали поклонятися їм, і роздратували Господа;","залишили Господа і стали служити Ваалу й Астарті.","І запалав гнів Господа на Ізраїля, і віддав їх у руки грабіжників, і грабували їх; і віддав їх у руки ворогів, які оточували їх, і не могли вже устояти перед ворогами своїми.","Куди б вони не пішли, рука Господня скрізь була їм на зло, як говорив їм Господь і як клявся їм Господь. І їм було дуже скрутно.","І поставив [їм] Господь суддів, які рятували їх від рук грабіжників їхніх;","але і суддів вони не слухали, а ходили блудно вслід інших богів і поклонялися їм [і дратували Господа], швидко ухилилися від путі, якою ходили батьки їхні, підкорюючись заповідям Господнім. Вони так не робили.","Коли Господь поставляв їм суддів, то Сам Господь був із суддею і рятував їх від ворогів їхніх в усі дні судді: бо жалів їх Господь, коли чув стогін їхній від тих, що гнітили і пригноблювали їх.","Але як тільки помирав суддя, вони знову робили гірше за батьків своїх, ухиляючись до інших богів, слугуючи їм і поклоняючись їм. Не відставали від діл своїх і [не відступали] від непокірливої путі своєї.","І запалав гнів Господній на Ізраїля, і сказав Він: за те, що народ цей переступає завіт Мій, який Я уклав з батьками їх, і не слухає голосу Мого,","і Я не стану вже виганяти від них жодного з тих народів, яких залишив Ісус, [син Навина, на землі,] коли помирав, —","щоб спокушати ними Ізраїля: чи стануть вони триматися путі Господньої і ходити по ній, як додержували батьки їхні, чи ні?","І залишив Господь народи ці і не вигнав їх невдовзі і не віддав їх у руки Ісуса."],"x":{"1":"1.3.2|1.14.19|0.17.7","2":"1.23.32|1.34.13","3":"5.23.13|1.23.33|1.34.12","6":"5.24.28","7":"5.24.31","8":"5.24.29","9":"5.19.50","11":"6.3.7","12":"26.29.18","13":"3.25.3|6.8.33","14":"6.3.8|25.43.13|31.50.1","16":"6.3.9|54.13.20","17":"2.17.7","18":"6.10.16","20":"6.3.8","21":"5.23.13","22":"4.8.2|6.3.4|50.6.13"},"n":{"5":["Ті, що плачуть."]}},{"v":["Ось ті народи, яких залишив Господь, щоб спокушати ними ізраїльтян, усіх, які не знали про всі війни ханаанські, —","для того тільки, щоб знали й училися війні наступні роди синів Ізраїлевих, які раніше не знали її:","п’ять власників филистимських, усі хананеї і, сидоняни й евеї, які живуть на горі Ливан, від гори Ваал-Ермона до входу в Емаф.","Вони були залишені, щоб спокушати ними ізраїльтян і довідатися, чи підкорюються вони заповідям Господнім, які Він заповів батькам їхнім через Мойсея.","І жили сини Ізраїлеві серед хананеїв, хеттеїв, аморреїв, ферезеїв, евеїв, [гергесеїв] та ієвусеїв,","і брали дочок їхніх собі за дружин, і своїх дочок віддавали за синів їхніх, і служили богам їх.","І зробили сини Ізраїлеві зле перед очима Господа, і забули Господа Бога свого, і служили Ваалу й Астарті.","І запалав гнів Господній на Ізраїля, і віддав їх у руки Хусарсафема, царя Месопотамського, і служили сини Ізраїлеві Хусарсафему вісім років.","Тоді заволали сини Ізраїлеві до Господа, і поставив Господь спасителя синам Ізраїлевим, який спас їх, Гофониїла, сина Кеназа, молодшого брата Халевового.","На ньому був Дух Господній, і був він суддею Ізраїля. Він вийшов на війну [проти Хусарсафема], і віддав Господь у руки його Хусарсафема, царя Месопотамського, і перемогла рука його Хусарсафема.","І спочивала земля сорок років. І помер Гофониїл, син Кеназа.","Сини Ізраїлеві знову стали робити зле перед очима Господа, і укріпив Господь Еглона, царя Моавитського, проти ізраїльтян, за те, що вони робили лихе перед очима Господа.","Він зібрав до себе [усіх] аммонитян і амаликитян, і пішов і уразив Ізраїля, й оволоділи вони містом Пальм.","І служили сини Ізраїлеві Еглону, царю Моавитському, вісімнадцять років.","Тоді воззвали сини Ізраїлеві до Господа, і Господь поставив їм спасителя Аода, сина Гери, сина Ієминиєвого, який був лівшою. І послали сини Ізраїлеві з ним дари Еглону, царю Моавитському.","Аод зробив собі меч із двома вістрями, довжиною в лікоть, і підперезав його під плащем своїм до правого стегна,","[і прийшов,] і підніс дари Еглону, царю Моавитському; Еглон же був чоловіком дуже повним.","Коли підніс Аод усі дари і випровадив людей, які принесли дари,","то сам повернувся від ідолів, що у Галгалі, і сказав: у мене є таємне слово до тебе, царю. Він сказав: тихіше! І вийшли від нього всі, хто стояв при ньому.","Аод увійшов до нього: він сидів у прохолодній світлиці, що була в нього окремо. І сказав Аод: у мене є до тебе, [царю,] слово Боже. [Еглон] встав зі стільця [перед ним].","[Коли він встав,] Аод простяг ліву руку свою і взяв меч із правого стегна свого і встромив його в живіт його,","так що ввійшло за вістрям і руків’я, і жир закрив вістря, тому що Аод не вийняв меча з живота його, і він пройшов до задньої частини.","І вийшов Аод за поріг, і зачинив за собою двері світлиці, і замкнув.","Коли він вийшов, раби Еглона прийшли і бачать, ось, двері світлиці замкнуті, і говорять: мабуть, він з необхідности у прохолодній кімнаті.","Чекали досить довго, але бачачи, що ніхто не відмикає дверей світлиці, взяли ключ і відімкнули, і ось, господар їхній лежить на землі мертвий.","Поки вони дивувалися, Аод тим часом пішов, [і ніхто про нього не думав,] пройшов повз ідолів і врятувався в Сеїраф.","Прийшовши ж [у землю Ізраїлеву, Аод] засурмив трубою на горі Єфремовій, і зійшли з ним сини Ізраїлеві з гори, і він ішов перед ними.","І сказав їм: ідіть за мною, бо віддав Господь [Бог] ворогів ваших моавитян у руки ваші. І пішли за ним, і захопили переправу через Йордан до Моаву, і не давали нікому переходити.","І вбили в той час моавитян близько десяти тисяч чоловік, усе здорових і сильних, і ніхто не втік.","Так підкорилися в той день моавитяни Ізраїлю, і спочивала земля вісімдесят років. [І був Аод суддею їх до самої смерти.]","Після нього був Самегар, син Анафів, який шістсот чоловік филистимлян побив волячим рожном; і він також спас Ізраїля."],"x":{"1":"1.23.29|4.7.22","3":"5.13.3|4.3.8","4":"4.8.2|6.2.22","6":"1.23.32|1.34.16|4.7.3","7":"32.7.9","8":"6.2.14","9":"5.15.17|6.2.16|6.4.3","11":"6.8.28","12":"6.4.1|6.6.1|8.12.9","20":"3.23.16","31":"6.5.6"}},{"v":["Коли помер Аод, сини Ізраїлеві стали знову робити зле перед очима Господа.","І віддав їх Господь у руки Іавина, царя Ханаанського, який царював у Асорі; воєначальником у нього був Сисара, який жив у Харошеф-Гоїмі.","І воззвали сини Ізраїлеві до Господа, тому що в нього було дев’ятсот залізних колісниць, і він жорстоко гнітив синів Ізраїлевих двадцять років.","У той час була суддею Ізраїля Девора пророчиця, дружина Лапидофова;","вона жила під Пальмою Девориною, між Рамою і Вефилем, на горі Єфремовій; і приходили до неї [туди] сини Ізраїлеві на суд.","[Девора] послала і покликала Варака, сина Авиноамового, з Кедеса Неффалимового, і сказала йому: повеліває [тобі] Господь Бог Ізраїлів: піди, піднімись на гору Фавор і візьми з собою десять тисяч чоловік із синів Неффалимових і синів Завулонових;","а Я приведу до тебе, до потоку Киссону, Сисару, воєначальника Іавинового, і колісниці його і багатолюдне [військо] його, і віддам його в руки твої.","Варак сказав їй: якщо ти підеш зі мною, піду; а якщо не підеш зі мною, не піду; [тому що я не знаю дня, в який пошле Господь ангела зі мною].","Вона сказала [йому]: піти піду з тобою; тільки [знай, що] не тобі вже буде слава в цьому поході, в який ти йдеш; але в руки жінки віддасть Господь Сисару. І встала Девора і пішла з Вараком у Кедес.","Варак скликав завулонян і неффалимлян у Кедес, і пішли слідом за ним десять тисяч чоловік, і Девора пішла з ним.","Хевер кенеянин відокремився тоді від кенеян, синів Ховава, родича Мойсеєвого, і розкинув намет свій біля діброви в Цааннимі біля Кедеса.","І донесли Сисарі, що Варак, син Авиноамів, піднявся на гору Фавор.","Сисара скликав усі колісниці свої, дев’ятсот залізних колісниць, і весь народ, який у нього, з Харошеф-Гоїма до потоку Киссону.","І сказала Девора Вараку: встань, тому що це той день, в який Господь віддасть Сисару в руки твої; Сам Господь піде перед тобою. І зійшов Варак з гори Фавор, і за ним десять тисяч чоловік.","Тоді Господь привів у замішання Сисару і всі колісниці його і все ополчення його від меча Варака, і зійшов Сисара з колісниці [своєї] і побіг пішки.","Варак переслідував колісниці [його] і ополчення до Харошеф-Гоїма, і загинуло все ополчення Сисарине від меча, не залишилося нікого.","Сисара ж утік пішки у намет Іаїлі, дружини Хевіра кенеянина; тому що між Іавином, царем Асорським, і домом Хевера кенеянина був мир.","І вийшла Іаїль назустріч Сисарі і сказала йому: зайди, господарю мій, зайди до мене, не бійся. Він зайшов до неї в намет, і вона покрила його килимом [своїм].","[Сисара] сказав їй: дай мені трохи води напитися, я пити хочу. Вона розв’язала міх з молоком, і напоїла його і знову покрила його.","[Сисара] сказав їй: стань біля дверей намету, і якщо хто прийде і запитає в тебе і скаже: «чи немає тут кого?», ти скажи: «ні».","Іаїль, дружина Хеверова, взяла кіл від намету, і взяла молот у руку свою, і підійшла до нього тихенько, і встромила кіл у скроню його так, що приколола до землі; а він спав від утоми — і помер.","І ось, Варак женеться за Сисарою. Іаїль вийшла назустріч йому і сказала йому: ввійди, я покажу тобі людину, яку ти шукаєш. Він увійшов до неї, і ось, Сисара лежить мертвим, і кіл у скроні його.","І смирив [Господь] Бог у той день Іавина, царя Ханаанського, перед синами Ізраїлевими.","Рука синів Ізраїлевих посилювалася більше і більше над Іавином, царем Ханаанським, доки не знищили вони Іавина, царя Ханаанського."],"x":{"2":"8.12.9","3":"6.3.9|5.17.16","6":"8.12.11","7":"6.5.21|10.18.40","10":"6.5.18","11":"3.10.29|3.24.21","14":"9.5.24","15":"25.82.10","16":"6.3.29","17":"25.82.10","19":"6.5.25","21":"19.13.1","23":"25.82.10"}},{"v":["У той день заспівали Девора і Варак, син Авиноамів, цими словами:","Ізраїль помстився, народ показав ревність; прославте Господа!","Слухайте, царі, прислухайтеся, вельможі: я Господу, я співаю, воздаю хвалу Господу Богу Ізраїлевому.","Коли виходив Ти, Господи, від Сеїра, коли йшов з поля Едомського, тоді земля тряслася, і небо капало, і хмари проливали воду;","гори танули від лиця Господа, навіть цей Синай від лиця Господа Бога Ізраїлевого.","У дні Самегара, сина Анафового, у дні Іаїлі, були порожні дороги, і ті, що ходили раніше путями прямими, ходили тоді обхідними дорогами.","Не стало мешканців у селищах у Ізраїля, не стало, доки не повстала я, Девора, доки не повстала я, мати в Ізраїлі.","Обрали нових богів, тому війна біля воріт. Чи видні були щит і спис у сорока тисяч Ізраїля?","Серце моє до вас, начальники Ізраїлеві, до ревнителів серед народу; прославте Господа!","Ті, хто їздить на ослицях білих, ті, що сидять на килимах і ходять по дорозі, співайте пісню!","Серед голосів, що збирають стада, біля колодязів, нехай співають хвалу Господу, хвалу вождям Ізраїля! Тоді виступив до воріт народ Господній.","Піднесися, піднесися, Деворо! піднесися, піднесися! співай пісню! Постань, Вараку! і веди полонених твоїх, сину Авиноамів!","Тоді небагатьом із сильних підкорив Він народ; Господь підпорядкував мені хоробрих.","Від Єфрема прийшли ті, хто вкорінився в Амалика; за тобою Веніамін, серед народу твого; від Махира йшли начальники, і від Завулона — ті, хто володіє тростиною писаря.","І князі Іссахарові з Деворою, й Іссахар так само, як Варак, кинувся в долину пішки. В племенах Рувимових велика розбіжність.","Чого сидиш ти між кошарами, слухаючи бекання отар? В племенах Рувимових велика розбіжність.","Галаад живе спокійно за Йорданом, і Дану чого боятися з кораблями? Асир сидить на березі моря й біля пристаней своїх живе спокійно.","Завулон — народ, який прирік душу свою на смерть, і Неффалим — на висотах поля.","Прийшли царі, зітнулися, тоді воювали царі ханаанські у Фанааху біля вод Мегиддонських, але не одержали ніякого срібла.","З неба воювали, зірки з путей своїх воювали із Сисарою.","Потік Киссон потягнув їх, потік Кедумим, потік Киссон. Зневажай, душе моя, силу!","Тоді ламалися копита кінські від утечі, від утечі сильних його.","Прокляніть Мероз, говорить ангел Господній, прокляніть, прокляніть жителів його за те, що не прийшли на допомогу Господу, на допомогу Господу з хоробрими.","Нехай буде благословенна між жонами Іаїль, дружина Хевера кенеянина, між жонами в наметах нехай буде благословенна!","Води просив він: молока подала вона, у чаші коштовній принесла молока кращого.","[Ліву] руку свою простягнула до кола, а праву свою до молота робітників; ударила Сисару, вразила голову його, розбила і проколола скроню його.","До ніг її схилився, упав і лежав, до ніг її схилився, упав; де схилився, там і впав убитий.","У вікно виглядає і волає мати Сисарина крізь ґрати: чому довго не йде кіннота його, чому баряться колеса колісниць його?","Розумні з її жінок відповідають їй, і сама вона відповідає на слова свої:","мабуть, вони знайшли, ділять здобич, по дівчині, по дві дівчини на кожного воїна, у здобич отримано різнобарвний одяг Сисарі, отримано у здобич різнобарвний одяг, вишитий з обох боків, знятий з плечей полоненого.","Так нехай загинуть усі вороги Твої, Господи! Ті ж, що люблять Його, нехай будуть, як сонце, що сходить у всій силі своїй! — І спочивала земля сорок років."],"x":{"4":"4.33.2|25.67.8","5":"1.19.18","6":"6.3.31","8":"8.13.22","10":"6.10.4","14":"6.3.15|12.2.55","15":"0.49.14","17":"5.13.24-25|5.19.24:40","18":"6.4.10|54.15.26","19":"25.75.6","20":"1.14.14|5.10.11","21":"6.4.7","22":"25.75.7","23":"6.2.1","25":"6.4.19","26":"19.13.8-9","31":"25.82.18|9.23.4|37.12.3"}},{"v":["Сини Ізраїлеві стали знову чинити зле перед очима Господа, і віддав їх Господь у руки мадіанитян на сім років.","Важка була рука мадіанитян над Ізраїлем, і сини Ізраїлеві зробили собі від мадіанитян ущелини в горах і печери й укріплення.","Коли посіє Ізраїль, прийдуть мадіанитяни й амаликитяни і жителі сходу і ходять у них;","і стоять у них наметами, і винищують плоди землі до самої Гази, і не залишають для прохарчування Ізраїлю ні вівці, ні вола, ні осла.","Тому що вони приходили з худобою своєю і з наметами своїми, приходили такою безліччю, як сарана; їм і верблюдам їхнім не було числа, і ходили по землі Ізраїлевій, щоб спустошувати її.","І дуже зубожів Ізраїль від мадіанитян, і воззвали сини Ізраїлеві до Господа.","І коли воззвали сини Ізраїлеві до Господа на мадіанитян,","послав Господь пророка до синів Ізраїлевих, і сказав їм: так говорить Господь Бог Ізраїлів: Я вивів вас з Єгипту, вивів вас з дому рабства;","визволив вас з руки єгиптян і з руки всіх, що гнобили вас, прогнав їх від вас, і дав вам землю їх,","і сказав вам: «Я — Господь Бог ваш; не шануйте богів аморрейських, у землі яких ви живете»; але ви не послухали голосу Мого.","І прийшов ангел Господній і сів у Офрі під дубом, що належав Іоасу, нащадкові Авиазеровому; син його Гедеон вибивав тоді пшеницю в точилі, щоб сховати від мадіанитян.","І явився йому ангел Господній і сказав йому: Господь з тобою, чоловіче сильний!","Гедеон сказав йому: господарю мій! якщо Господь з нами, то чого сталася з нами уся ця [біда]? і де всі чудеса Його, про які розповідали нам батьки наші, говорячи: «з Єгипту вивів нас Господь»? Нині залишив нас Господь і віддав нас у руки мадіанитян.","Господь, споглянувши на нього, сказав: іди з цією силою твоєю і спаси Ізраїля від руки мадіанитян; Я посилаю тебе.","[Гедеон] сказав йому: Господи! як спасу я Ізраїля? ось, і плем’я моє в коліні Манассіїному найбідніше, і я в домі батька мого молодший.","І сказав йому Господь: Я буду з тобою, і ти подолаєш мадіанитян, як одну людину.","[Гедеон] сказав Йому: якщо я знайшов благодать перед очима Твоїми, то зроби мені знамення, що Ти говориш зі мною:","не йди звідси, доки я не прийду до Тебе і не принесу дара мого і не запропоную Тобі. Він сказав: Я залишуся до повернення твого.","Гедеон пішов і приготував козеня й опрісноків з ефи борошна; м’ясо поклав у кошик, а юшку влив у горщик і приніс до Нього під дуб і запропонував.","І сказав йому ангел Божий: візьми м’ясо й опрісноки, і поклади на цей камінь, і вилий юшку. Він так і зробив.","Ангел Господній простяг кінець жезла, який був у руці його, доторкнувся до м’яса й опрісноків; і вийшов вогонь з каменя і поїв м’ясо й опрісноки; і ангел Господній зник з очей його.","І побачив Гедеон, що це ангел Господній, і сказав Гедеон: горе мені, Владико Господи! тому що я бачив ангела Господнього лицем до лиця.","Господь сказав йому: мир тобі, не бійся, не помреш.","І влаштував там Гедеон жертовник Господу і назвав його: Ієгова Шалом*. Він ще до цього дня в Офрі Авиєзеровій.","У ту ніч сказав йому Господь: візьми тельця зі стада батька твого й другого тельця семирічного, і зруйнуй жертовник Ваала, який у батька твого, і зрубай священне дерево, яке при ньому,","і постав жертовник Господу Богу твоєму, [який явився тобі] на вершині скелі цієї, у порядку, і візьми другого тельця і принеси у всепалення на дровах дерева, яке зрубаєш.","Гедеон взяв десять чоловік з рабів своїх і зробив, як говорив йому Господь; але оскільки зробити це вдень він боявся через домашніх батька свого і жителів міста, то зробив уночі.","Зранку встали жителі міста, і ось, жертовник Ваала зруйнований, і дерево при ньому зрубано, і другий телець принесений у всепалення на новоспорудженому жертовнику.","І говорили одне одному: хто це зробив? Шукали, розпитували і сказали: Гедеон, син Іоасів, зробив це.","І сказали жителі міста Іоасу: виведи сина твого; він повинен померти за те, що зруйнував жертовник Ваала і зрубав дерево, яке було при ньому.","Іоас сказав усім, хто приступив до нього: чи вам заступатися за Ваала, чи вам захищати його? хто заступиться за нього, той буде відданий на смерть в цей самий ранок; якщо він бог, то нехай сам заступиться за себе, проти того, хто зруйнував його жертовник.","І став називати його з того дня Ієроваалом, тому що сказав: нехай Ваал сам судиться з ним за те, що він зруйнував жертовник його.","Тим часом усі мадіанитяни й амаликитяни і жителі сходу зібралися разом, перейшли [ріку] і стали станом у долині Ізреельській.","І Дух Господній надихнув Гедеона; він засурмив трубою, і скликане було плем’я Авиєзерове, щоб іти за ним.","І послав послів по всьому коліну Манассіїному, і воно погодилося йти за ним; також послав послів до Асира, Завулона і Неффалима, і ці прийшли назустріч їм.","І сказав Гедеон Богу: якщо Ти спасеш Ізраїля рукою моєю, як говорив Ти,","то ось, я розстелю тут на току стрижену вовну: якщо роса буде тільки на вовні, а на усій землі сухо, то буду знати, що спасеш рукою моєю Ізраїля, як говорив Ти.","Так і сталося: на другий день, вставши рано, він став віджимати вовну і віджав з вовни роси цілу чашу води.","І сказав Гедеон Богові: не прогнівайся на мене, якщо ще раз скажу і ще тільки один раз зроблю випробування над вовною: нехай буде сухо на одній тільки вовні, а на всій землі нехай буде роса.","Бог так і зробив у ту ніч: тільки на вовні було сухо, а на всій землі була роса."],"x":{"1":"6.3.12|3.25.17-18","2":"9.17.9","3":"4.28.33|6.8.11","5":"6.7.12","7":"6.3.9","10":"11.17.35","11":"6.2.1|6.5.23|8.12.11","12":"7.2.4|52.1.28","13":"25.12.2","14":"8.12.11","15":"1.4.10|8.9.21","16":"1.3.12|3.14.15","17":"52.2.12","18":"6.13.15","21":"2.9.24","22":"0.16.13|1.19.21","23":"6.19.20|8.25.6","24":"0.22.14|1.17.15|31.9.6","25":"4.7.5","29":"6.15.6","31":"10.18.21","32":"6.7.1|8.12.11|9.11.21","33":"38.1.5","34":"6.11.29|8.16.13","37":"25.71.6","39":"0.18.32"},"n":{"24":["Господь — мир."]}},{"v":["Ієроваал, він же і Гедеон, встав зранку і весь народ, який був з ним, і розташувалися станом біля джерела Харода; мадіамський же стан був від нього на північ біля пагорба Море? на долині.","І сказав Господь Гедеону: народу з тобою занадто багато, не можу Я віддати мадіанитян у руки їх, щоб не загордився Ізраїль переді Мною і не сказав: «моя рука спасла мене»;","отже, виголоси голосно до народу і скажи: «хто боязкий і несміливий, той нехай повернеться і йде назад з гори Галаада». І повернулося народу двадцять дві тисячі, а десять тисяч залишилося.","І сказав Господь Гедеону: все ще багато народу; веди їх до води, там Я виберу з них тобі; про кого Я скажу: «нехай іде з тобою», той і нехай іде з тобою; а про кого скажу тобі: «не повинен іти з тобою», той нехай і не йде.","Він привів народ до води. І сказав Господь Гедеону: хто буде хлебтати воду язиком своїм, як хлебче пес, того постав окремо, також і тих усіх, які будуть схилятися на коліна свої і пити.","І було число тих, хто хлебтали ротом своїм з руки, триста чоловік; весь же інший народ схилявся на коліна свої пити воду.","І сказав Господь Гедеону: трьомастами тими, що хлебтали, Я спасу вас і віддам мадіанитян у руки ваші, а весь народ нехай іде, кожен у своє місце.","І взяли вони у народу запас їжі собі і труби їхні, і відпустив Гедеон усіх ізраїльтян по наметах і затримав у себе триста чоловік; стан же мадіамський був у нього внизу в долині.","У ту ніч сказав йому Господь: встань, зійди в стан, Я віддаю його в руки твої;","якщо ж ти боїшся йти один, то піди в стан ти і Фура, слуга твій;","і почуєш, що говорять, і тоді укріпляться руки твої, і підеш у стан. І зійшов він і Фура, слуга його, до самого полку озброєних, які були в стані.","Мадіанитяни ж і амаликитяни і всі жителі сходу розташувалися на долині в такій безлічі, як сарана; верблюдам їх не було числа, багато було їх, як піску на березі моря.","Гедеон прийшов. І ось, один розповідає іншому сон і говорить: снилося мені, начебто круглий ячмінний хліб котився по стану мадіамському і, прикотившись до намету, вдарив у нього так, що він упав, перекинув його, і намет розпався.","Інший сказав у відповідь йому: це не що інше, як меч Гедеона, сина Іоасового, ізраїльтянина; віддав Бог у руки його мадіанитян і весь стан.","Гедеон, почувши розповідь про сон і тлумачення його, вклонився [Господу] і повернувся в стан ізраїльський і сказав: вставайте! віддав Господь у руки ваші стан мадіамський.","І розділив триста чоловік на три загони і дав у руки всім їм труби і порожні глечики і в глечики світильники.","І сказав їм: дивіться на мене і робіть те саме; ось, я підійду до стану, і що буду робити, те і ви робіть;","коли я і ті, що знаходяться зі мною, засурмимо трубами, сурміть і ви трубами вашими навколо всього стану і кричіть: [меч] Господа і Гедеона!","І підійшов Гедеон і сто чоловік з ним до стану, на початку середньої сторожі, і розбудили вартових, і засурмили трубами і розбили глечики, що були в руках їхніх.","І засурмили всі три загони трубами, і розбили глечики, і тримали в лівій руці своїй світильники, а в правій руці труби, і сурмили, і кричали: меч Господа і Гедеона!","І стояв кожен на своєму місці навколо стану; і стали бігати в усьому стані, і кричали, і кинулися втікати.","У той час як триста чоловік сурмили трубами, повернув Господь меч один на одного в усьому стані, і побігло ополчення до Бефшитти, до Царери, до межі Авелмехоли, поблизу Табафи.","І скликали ізраїльтян з коліна Неффалимового, Асирового і всього коліна Манассіїного, і погналися за мадіанитянами.","Гедеон же послав послів на всю гору Єфремову сказати: вийдіть назустріч мадіанитянам і перехопіть у них переправу через воду до Бефвари і Йордан. І скликали всіх єфремлян, і перехопили вони переправи через воду до Бефвари і Йордан;","і впіймали двох князів мадіамських: Орива і Зива, і вбили Орива в Цур-Ориві, а Зива в Ієкев-Зиві і переслідували мадіанитян; голови ж Орива і Зива принесли до Гедеона за Йордан."],"x":{"1":"6.6.32","2":"4.8.17","3":"4.20.8","4":"8.14.6","7":"13.14.11|21.3.18|50.14.19","10":"27.4.9","12":"6.6.5","15":"0.24.26|31.9.4","16":"6.9.34","18":"1.14.14","21":"25.82.10","22":"25.82.18","24":"53.1.28","25":"25.82.12|31.10.26"}},{"v":["І сказали йому єфремляни: навіщо ти це зробив, чому не покликав нас, коли йшов воювати з мадіанитянами? І сильно сварилися з ним.","[Гедеон] відповів їм: чи зробив я щось таке, як ви нині? Чи не краще Єфрем добирав виноград, ніж Авиєзер збирав?","У ваші руки віддав Бог князів мадіамських Орива і Зива, і що міг зробити я такого, як ви? Тоді заспокоївся дух їх проти нього, коли сказав він їм такі слова.","І прийшов Гедеон до Йордану, і перейшов сам і триста чоловік, які були з ним. Вони були стомлені [і голодні], переслідуючи ворогів.","І сказав він жителям Сокхофа: дайте хліба народу, який іде за мною; вони стомилися, а я переслідую Зевея і Салмана, царів мадіамських.","Князі Сокхофа сказали: хіба рука Зевея і Салмана вже у твоїй руці, щоб нам війську твоєму давати хліб?","І сказав Гедеон: за це, коли віддасть Господь Зевея і Салмана в руки мої, я роздеру тіло ваше терням пустельним і молотильними зубчастими дошками.","Звідти пішов він у Пенуел і те саме сказав жителям його, і жителі Пенуела відповіли йому те саме, що відповідали жителі Сокхофа.","Він сказав жителям Пенуела: коли я повернуся у мирі, зруйную вежу цю.","Зевей же і Салман були в Каркорі і з ними їхнє ополчення до п’ятнадцяти тисяч, усе, що залишилося з усього ополчення жителів сходу; загинуло ж сто двадцять тисяч чоловік, які оголюють меч.","Гедеон пішов до тих, що живуть у наметах на схід від Нови й Іогбеги й уразив стан, коли стан спочивав безтурботно.","Зевей і Салман побігли; він погнався за ними і схопив обох царів мадіамських, Зевея і Салмана, і весь стан привів у замішання.","І повернувся Гедеон, син Іоаса, з війни з узвишшя Хереса.","І захопив юнака з жителів Сокхофа і випитав у нього; і він написав йому князів і старійшин сокхофських сімдесят сім чоловік.","І прийшов він до жителів сокхофських, і сказав: ось Зевей і Салман, за яких ви насміялися з мене, говорячи: хіба рука Зевея і Салмана вже у твоїй руці, щоб нам давати хліб людям твоїм, які стомилися?","І взяв старійшин міста і терен пустельний і зубчасті молотильні дошки і покарав ними жителів Сокхофа;","і вежу Пенуельську зруйнував, і перебив жителів міста.","І сказав Зевею і Салману: якими були ті, яких ви вбили на Фаворі? Вони сказали: вони були такі, як ти, кожен мав вигляд синів царських.","[Гедеон] сказав: це були брати мої, сини матері моєї. Живий Господь! якби ви залишили їх живими, я не убив би вас.","І сказав Ієферу, первісткові своєму: встань, убий їх. Але юнак не витяг меча свого, тому що боявся, оскільки був ще молодим.","І сказали Зевей і Салман: встань сам і убий нас, тому що за людиною і сила її. І встав Гедеон, і убив Зевея і Салмана, і взяв пряжки, що були на шиях верблюдів їхніх.","І сказали ізраїльтяни Гедеону: володій нами ти і син твій і син сина твого, тому що ти спас нас від руки мадіанитян.","Гедеон сказав їм: ні я не буду володіти вами, ні мій син не буде володіти вами; Господь нехай володіє вами.","І сказав їм Гедеон: прошу у вас одного, дайте мені кожен по серзі зі здобичі своєї. [Бо у ворогів багато було золотих серг, тому що вони були ізмаїльтяни.]","Вони сказали: дамо. І розстелили одяг і кидали туди кожен по серзі зі здобичі своєї.","Ваги у золотих сергах, які він випросив, було тисяча сімсот золотих [сиклів], крім пряжок, ґудзиків і пурпурового одягу, що були на царях мадіамських, і крім [золотих] ланцюжків, що були на шиї у верблюдів їхніх.","З цього зробив Гедеон ефод і поклав його у своєму місті, в Офрі, і стали всі ізраїльтяни блудно ходити туди за ним, і був він сіттю Гедеону і всьому дому його.","Так підкорилися мадіанитяни синам Ізраїля і не стали вже піднімати голови своєї, і спочивала земля сорок років у дні Гедеона.","І пішов Ієроваал, син Іоасів, і жив у домі своєму.","У Гедеона було сімдесят синів, які народилися від стегон його, тому що в нього багато було дружин.","Також і наложниця, яка жила в Сихемі, народила йому сина, і він дав йому ім’я Авимелех.","І помер Гедеон, син Іоаса, у глибокій старості, і похований був у гробі батька свого Іоаса, в Офрі Авиєзеровій.","Коли помер Гедеон, сини Ізраїлеві знову стали блудно ходити вслід Ваалу і поставили собі богом Ваалверифа;","і не згадували сини Ізраїлеві Господа Бога свого, Який спас їх від руки всіх ворогів, які оточували їх;","і дому Ієровааловому, або Гедеоновому, не зробили милости за всі благодіяння, які він зробив Ізраїлю."],"x":{"1":"6.12.1","2":"6.6.34|5.17.2","3":"6.7.25","5":"5.13.27","8":"0.32.30|10.12.25","10":"6.20.2","11":"3.32.42","12":"38.10.14","18":"5.19.12","20":"5.10.24","21":"25.82.12","27":"2.20.5|1.23.33","28":"6.3.11","30":"11.10.1","31":"6.9.1","33":"6.3.7|6.9.4|32.23.27","35":"6.9.5"}},{"v":["Авимелех, син Ієроваалів, пішов у Сихем до братів матері своєї і говорив їм і всьому племені батька матері своєї, і сказав:","скажіть усім жителям сихемським: що краще для вас, щоб володіли вами всі сімдесят синів Ієроваалових, чи щоб володів один? і згадайте, що я кість ваша і плоть ваша.","Брати матері його сказали всі ці слова його жителям сихемським; і прихилилося серце їхнє до Авимелеха, бо говорили вони: він брат наш.","І дали йому сімдесят сиклів срібла з дому Ваалверифа; Авимелех найняв за них бездільних і свавільних людей, які й пішли за ним.","І прийшов він у дім батька свого в Офру й убив братів своїх, сімдесят синів Ієроваалових, на одному камені. Залишився тільки Іофам, молодший син Ієроваалів, тому що сховався.","І зібралися всі жителі сихемські і весь дім Милло, і пішли і поставили царем Авимелеха біля дуба, що поблизу Сихема.","Коли розповіли про це Іофаму, він пішов і став на вершині гори Гаризим і, піднесши голос свій, кричав і говорив їм: послухайте мене, жителі Сихема, і послухає вас Бог!","Пішли колись дерева помазати над собою царя і сказали маслиновому дереву: царюй над нами.","Маслина сказала їм: чи залишу я жир мій, яким ушановують богів і людей і чи піду блукати по деревах?","І сказали дерева смоковниці: йди ти, царюй над нами.","Смоковниця сказала їм: чи залишу я солодкість мою і гарний плід мій і чи піду блукати по деревах?","І сказали дерева виноградній лозі: йди ти, царюй над нами.","Виноградна лоза сказала їм: чи залишу я сік мій, який веселить богів і людей, і чи піду блукати по деревах?","Нарешті сказали всі дерева терну: йди ти, царюй над нами.","Терен сказав деревам: якщо ви дійсно поставляєте мене царем над собою, то йдіть, спочивайте під тінню моєю; якщо ж ні, то вийде вогонь з терну і спалить кедри ливанські.","Отже, дивіться, чи істино і чи справедливо ви зробили, поставивши Авимелеха царем? І чи добре ви зробили з Ієроваалом і домом його, і чи відповідно до його благодіянь вчинили ви?","За вас батько мій воював, не щадив життя свого і визволив вас від руки мадіанитян;","а ви тепер повстали проти дому батька мого, й убили сімдесят синів батька мого на одному камені, і поставили царем над жителями сихемськими Авимелеха, сина рабині його, тому що він брат ваш.","Якщо ви нині за істиною і за правдою вчинили з Ієроваалом і домом його, то [нехай буде на вас благословення і] радуйтеся за Авимелеха, і він нехай радується за вас;","якщо ж ні, то нехай вийде вогонь від Авимелеха і нехай спалить жителів сихемських і весь дім Милло і нехай вийде вогонь від жителів сихемських і від дому Милло, і нехай попалить Авимелеха.","І побіг Іофам, і втік і пішов у Беер, і жив там, ховаючись від брата свого Авимелеха.","Авимелех же царював над Ізраїлем три роки.","І послав Бог злого духа на Авимелеха і на жителів Сихема, і не стали підкорятися жителі сихемські Авимелеху,","щоб у такий спосіб звершилася помста за сімдесят синів Ієроваалових, і кров їхня повернулася на Авимелеха, брата їхнього, який убив їх, і на жителів сихемських, які укріпили руки його, щоб убити братів своїх.","Жителі сихемські посадили проти нього в засідку людей на вершинах гір, які грабували кожного, хто проходив мимо них по дорозі. Про це донесено було Авимелеху.","Прийшов же і Гаал, син Еведів, з братами своїми в Сихем, і ходили вони по Сихему, і жителі сихемські поклалися на нього.","І вийшли в поле, і збирали виноград свій, і давили в точилах, і справляли свята, ходили в дім бога свого, і їли і пили, і проклинали Авимелеха.","Гаал, син Еведів, говорив: хто Авимелех і що Сихем, щоб ми служили йому? Чи не син він Ієроваалів, і чи не Зевул головначальник його? Служіть краще нащадкам Еммора, батька Сихемового, а йому чому ми повинні служити?","Якби хто дав народ цей у руки мої, я прогнав би Авимелеха. І сказано було Авимелеху: примнож військо твоє і виходь.","Зевул, начальник міста, почув слова Гаала, сина Еведового, і запалав гнів його.","Він хитрим способом відправляє послів до Авимелеха, щоб сказати: ось, Гаал, син Еведів, і брати його прийшли в Сихем, і ось, вони підбурюють проти тебе місто;","отже, встань уночі, ти і народ, який знаходиться з тобою, і постав засідку в полі;","вранці ж, при сходженні сонця, встань рано і підійди до міста; і коли він і народ, який з ним, вийдуть до тебе, тоді роби з ними, що може рука твоя.","І встав уночі Авимелех і весь народ, який знаходився з ним, і поставили в засідку біля Сихема чотири загони.","[Вранці] Гаал, син Еведів, вийшов і став біля воріт міських; і встав Авимелех і народ, який був з ним, із засідки.","Гаал, побачивши народ, говорить Зевулу: ось, народ спускається з вершини гір. А Зевул сказав йому: тінь гір тобі здається людьми.","Гаал знову говорив і сказав: ось, народ спускається з узвишшя, і один загін іде від дуба Меонним.","І сказав йому Зевул: де вуста твої, які говорили: «хто Авимелех, щоб ми служили йому?» Це той народ, який ти зневажав; виходь тепер і воюй з ним.","І пішов Гаал попереду жителів сихемських і воював з Авимелехом.","І погнався за ним Авимелех, і побіг він від нього, і багато впало убитих до самих воріт міста.","І залишився Авимелех в Арумі, а Гаала і братів його Зевул вигнав, щоб вони не жили в Сихемі.","На другий день вийшов народ у поле, і донесли про це Авимелеху.","Він узяв свій народ і розділив його на три загони і поставив у засідку в полі. І, побачивши, що народ вийшов з міста, повстав на них і побив їх.","Тим часом як Авимелех і загони, які були з ним, підійшли і стали біля воріт міських, інші два загони напали на всіх, хто був у полі, й убивали їх.","І бився Авимелех з містом увесь той день, і взяв місто, і перебив людей, які були в ньому, і зруйнував місто і засіяв його сіллю.","Почувши про це, всі, хто був у вежі сихемській, пішли у вежу капища Ваал-Верифа.","Авимелеху донесли, що зібралися там усі, хто був раніше у вежі сихемській.","І пішов Авимелех на гору Селмон, сам і весь народ, який був з ним, і взяв Авимелех сокири із собою і нарубав сучків з дерев, і поклав на плечі свої, і сказав людям, які були з ним: ви бачили, що я робив; скоріше робіть і ви те саме, що я.","І нарубав кожен з усього народу сучків, і пішли за Авимелехом, і поклали до вежі, і спалили за допомогою їх вежу вогнем, і померли всі, хто був у вежі сихемській, близько тисячі чоловіків і жінок.","Потім пішов Авимелех у Тевец і обложив Тевец і взяв його.","Посеред міста була міцна вежа, і втекли туди всі чоловіки і жінки і всі жителі міста, і замкнулися і зійшли на покрівлю вежі.","Авимелех прийшов до вежі й оточив її і підійшов до дверей вежі, щоб спалити її вогнем.","Тоді одна жінка кинула уламок жорна на голову Авимелеху і проломила йому череп.","[Авимелех] негайно покликав отрока, зброєносця свого, і сказав йому: оголи меч твій і умертви мене, щоб не сказали про мене: жінка убила його. І проколов його отрок його, і він помер.","Ізраїльтяни, бачачи, що помер Авимелех, пішли кожен у своє місце.","Так воздав Бог Авимелеху за злодіяння, які він зробив батькові своєму, убивши сімдесят братів своїх.","І всі злодіяння жителів сихемських повернув Бог на голову їх; і спостигло їх прокляття Іофама, сина Ієроваалового."],"x":{"1":"6.8.31","2":"6.8.31|9.5.1","4":"0.20.16","5":"11.10.7:14","6":"5.24.26","7":"4.11.29","8":"16.4.13","13":"25.103.15","15":"36.5.4|36.19.14","17":"6.5.18|6.12.3|8.19.5","23":"8.16.14","24":"9.1.16|25.7.17|50.27.25","27":"36.18.6","28":"0.34.2","32":"5.8.2","33":"2.25.28|8.10.7","45":"4.29.23|46.2.9","48":"25.67.15","50":"9.11.21","53":"9.11.21","57":"6.9.20"}},{"v":["Після Авимелеха постав для спасіння Ізраїля Фола, син Фуї, сина Додового, з коліна Іссахарового. Він жив у Шамирі на горі Єфремовій.","Він був суддею Ізраїля двадцять три роки, і помер, і похований у Шамирі.","Після нього постав Іаїр з Галаада і був суддею Ізраїля двадцять два роки.","У нього було тридцять [два] сини, які їздили на тридцятьох [двох] молодих ослах, і тридцять [два] міста було в них; до цього дня їх називають селищами Іаїра, що в землі Галаадській.","І помер Іаїр і був похований у Камоні.","Сини Ізраїлеві продовжували чинити зле перед очима Господа і служили Ваалу й Астарті, і богам арамейським, і богам сидонським, і богам моавитським, і богам аммонитським, і богам филистимським; а Господа залишили і не служили Йому.","І запалав гнів Господа на Ізраїля, і Він віддав їх у руки филистимлян і в руки аммонитян;","вони утискували і мучили синів Ізраїлевих з того року вісімнадцять років, усіх синів Ізраїлевих по той бік Йордану в землі Аморрейській, що у Галааді.","Нарешті аммонитяни перейшли Йордан, щоб вести війну з Іудою і Веніаміном і з домом Єфремовим. І дуже тісно було синам Ізраїля.","І воззвали сини Ізраїлеві до Господа, і говорили: згрішили ми перед Тобою, тому що залишили Бога нашого і служили Ваалу.","І сказав Господь синам Ізраїлевим: чи не пригнічували вас єгиптяни, й аморреяни, й аммонитяни, і филистимляни,","і сидоняни, й амаликитяни, і моавитяни, і коли ви взивали до Мене, чи не спасав Я вас від рук їх?","А ви залишили Мене і стали служити іншим богам; за те Я вже не буду спасати вас:","підіть, взивайте до богів, яких ви обрали, нехай вони спасають вас у скрутний для вас час.","І сказали сини Ізраїлеві Господу: згрішили ми; роби з нами все, що Тобі завгодно, тільки визволи нас нині.","І відкинули від себе чужих богів і стали служити [тільки] Господу. І не потерпіла душа Його страждання Ізраїлевого.","Аммонитяни зібралися і розташувалися станом біля Галаада; зібралися також сини Ізраїлеві і стали станом у Массифі.","Народ і князі галаадські сказали одне одному: хто почне війну проти аммонитян, той буде начальником над усіма жителями галаадськими."],"x":{"3":"0.31.21|3.32.1","4":"6.5.10","6":"6.2.11:13|8.7.3","7":"6.2.14|8.12.9","10":"6.3.9","13":"4.32.15|32.2.13|10.18.27","16":"0.35.4|6.2.18","17":"6.11.11","18":"6.11.6"}},{"v":["Ієффай галаадитянин був людиною хороброю. Він був сином блудниці; від Галаада народився Ієффай.","І дружина Галаадова народила йому синів. Коли змужніли сини дружини, прогнали вони Ієффая, сказавши йому: ти не спадкоємець у домі батька нашого, тому що ти син іншої жінки.","І втік Ієффай від братів своїх і жив у землі Тов; і зібралися до Ієффая бездільні люди і виходили з ним.","Через деякий час аммонитяни пішли війною на Ізраїля.","Під час війни аммонитян з ізраїльтянами прийшли старійшини галаадські взяти Ієффая із землі Тов","і сказали Ієффаю: прийди, будь у нас вождем, і ми будемо воювати з аммонитянами.","Ієффай сказав старійшинам галаадським: чи не ви зненавиділи мене і вигнали з дому батька мого? навіщо ж прийшли до мене нині, коли ви в біді?","Старійшини галаадські сказали Ієффаю: для того ми тепер прийшли до тебе, щоб ти пішов з нами й воював з аммонитянами і був у нас начальником усіх жителів галаадських.","І сказав Ієффай старійшинам галаадським: якщо ви повернете мене, щоб воювати з аммонитянами, і Господь віддасть їх мені, то чи залишуся я у вас начальником?","Старійшини галаадські сказали Ієффаю: Господь нехай буде свідком між нами, що ми зробимо за словом твоїм!","І пішов Ієффай зі старійшинами галаадськими, і народ поставив його над собою начальником і вождем, і Ієффай виголосив усі слова свої перед лицем Господа в Массифі.","І послав Ієффай послів до царя Аммонитського сказати: що тобі до мене, чому ти прийшов до мене воювати на землі моїй?","Цар Аммонитський сказав послам Ієффая: Ізраїль, коли йшов з Єгипту, взяв землю мою від Арнона до Іавока і Йордану; отже, поверни мені її з миром [і я відступлю].","[І повернулися посли до Ієффая.] Ієффай удруге послав послів до царя Аммонитського,","сказати йому: так говорить Ієффай: Ізраїль не забирав землі Моавитської і землі Аммонитської;","бо коли йшли з Єгипту, Ізраїль пішов у пустелю до Червоного моря і прийшов у Кадес;","звідти послав Ізраїль послів до царя Едомського сказати: «дозволь мені пройти землею твоєю»; але цар Едомський не послухав; і до царя Моавитського він посилав, але і той не погодився; тому Ізраїль залишався в Кадесі.","І пішов пустелею, й оминув землю Едомську і землю Моавитську, і, прийшовши до східної межі землі Моавитської, розташувався станом за Арноном; але не входив у межі Моавитські, тому що Арнон є межа Моава.","І послав Ізраїль послів до Сигона, царя Аморрейського, царя Есевонського, і сказав йому Ізраїль: дозволь нам пройти землею твоєю в своє місце.","Але Сигон не погодився пропустити Ізраїля через межі свої, і зібрав Сигон весь народ свій, і розташувався станом у Іааці, і воював з Ізраїлем.","І віддав Господь Бог Ізраїлів Сигона і весь народ його в руки Ізраїля, і він розбив їх; і одержав Ізраїль у спадщину всю землю Аморрея, що жив у землі тій;","і одержали вони у спадщину всі землі Аморрея від Арнона до Іавока і від пустелі до Йордану.","Отже, Господь Бог Ізраїлів прогнав Аморрея від імені народу Свого Ізраїля, а ти хочеш узяти його спадщину?","Чи не володієш ти тим, що дав тобі Хамос, бог твій? І ми володіємо всім тим, що дав нам у спадщину Господь Бог наш.","Хіба ти кращий за Валака, сина Сепфорового, царя Моавитського? Чи сварився він з Ізраїлем, або воював з ними?","Ізраїль уже живе триста років у Есевоні й у залежних від нього містах, у Ароері і залежних від нього містах, і в усіх містах, що біля Арнона; чому ви в той час не віднімали [їх]?","А я не винен перед тобою, і ти робиш мені зло, виступивши проти мене війною. Господь Суддя нехай буде нині суддею між синами Ізраїля і між аммонитянами!","Але цар Аммонитський не послухав слів Ієффая, з якими він посилав до нього.","І був на Ієффаєві Дух Господній, і пройшов він Галаад і Манассію, і пройшов Массифу галаадську, і з Массифи галаадської пішов до аммонитян.","І дав Ієффай обітницю Господу і сказав: якщо Ти віддаси аммонитян у руки мої,","то після повернення мого з миром від аммонитян, що вийде з воріт дому мого назустріч мені, буде Господу, і принесу це у всепалення.","І прийшов Ієффай до аммонитян — воювати з ними, і віддав їх Господь у руки його;","і вразив їх поразкою дуже великою, від Ароера до Минифа двадцять міст, і до Авель-Керамима, і підкорилися аммонитяни синам Ізраїлевим.","І прийшов Ієффай у Массифу в дім свій, і ось, дочка його виходить назустріч йому з тимпанами і бубнами: вона була в нього тільки одна, і не було в нього ще ні сина, ні дочки.","Коли він побачив її, роздер одяг свій і сказав: ох, дочко моя! ти вбила мене; і ти серед порушників спокою мого! я відкрив [про тебе] вуста мої перед Господом і не можу відректися.","Вона сказала йому: батьку мій! ти відкрив вуста твої перед Господом — і роби зі мною те, що вимовили вуста твої, коли Господь звершив через тебе помсту ворогам твоїм аммонитянам.","І сказала батькові своєму: зроби мені тільки ось що: відпусти мене на два місяці; я піду, зійду на гори й оплачу дівоцтво моє з подругами моїми.","Він сказав: піди. І відпустив її на два місяці. Вона пішла з подругами своїми й оплакувала дівоцтво своє в горах.","Коли минуло два місяці вона повернулася до батька свого, і він звершив над нею обітницю свою, яку дав, і вона не пізнала чоловіка. І ввійшло у звичай у Ізраїля,","що щорічно дочки Ізраїлеві ходили оплакувати дочку Ієффая галаадянина, чотири дні на рік."],"x":{"1":"75.11.32","2":"0.21.10","3":"8.22.2","8":"6.10.18","10":"49.2.14","11":"8.12.11","12":"4.20.10","13":"3.21.13:24","15":"4.2.19","17":"3.20.14:17","18":"3.21.13","19":"3.21.21","21":"3.21.24","23":"40.2.9","24":"10.11.7|11.23.13","25":"3.22.2","27":"0.16.5","29":"6.6.34|6.13.25|52.1.35","33":"4.3.12","34":"1.15.20|8.18.6|25.67.26","35":"0.37.29:34"}},{"v":["Єфремляни зібралися і перейшли в Севину і сказали Ієффаю: для чого ти ходив воювати з аммонитянами, а нас не покликав із собою? ми спалимо дім твій вогнем і з тобою разом.","Ієффай сказав їм: я і народ мій мали з аммонитянами велику сварку; я кликав вас, але ви не спасли мене від рук їх;","бачачи, що ви не спасаєте мене, я піддав небезпеці життя моє і пішов на аммонитян, і віддав їх Господь у руки мої; навіщо ж ви прийшли нині воювати зі мною?","І зібрав Ієффай усіх жителів галаадських і воював з єфремлянами, і розбили жителі галаадські єфремлян, говорячи: ви утікачі Єфремові, Галаад же серед Єфрема і серед Манассії.","І перехопили галаадитяни переправу через Йордан від єфремлян, і коли хто з уцілілих єфремлян говорив: «дозвольте мені переправитися», то жителі галаадські говорили йому: чи не єфремлянин ти? Він говорив: ні.","Вони говорили йому: «скажи: шибболет», а він говорив: «сибболет», і не міг інакше вимовити. Тоді вони, узявши його, заколювали біля переправи через Йордан. І загинуло в той час єфремлян сорок дві тисячі.","Ієффай був суддею Ізраїля шість років, і помер Ієффай галаадитянин і похований в одному з міст галаадських.","Після нього був суддею Ізраїля Есевон з Вифлеєма.","У нього було тридцять синів, і тридцять дочок відпустив він з дому [заміж], а тридцять дочок узяв зі сторони за синів своїх, і був суддею Ізраїля сім років.","І помер Есевон і похований у Вифлеємі.","Після нього був суддею Ізраїля Елон завулонянин і судив Ізраїль десять років.","І помер Елон завулонянин і похований в Аїалоні, в землі Завулоновій.","Після нього був суддею Ізраїля Авдон, син Гиллела, пирафонянин.","У нього було сорок синів і тридцять онуків, які їздили на сімдесяти молодих ослах; він судив Ізраїль вісім років.","І помер Авдон, син Гиллела, пирафонянин, і похований у Пирафоні в землі Єфремовій, на горі Амаликовій."],"x":{"1":"6.8.1","3":"6.5.18|6.9.17","4":"9.18.6","6":"50.26.73","8":"5.19.15","12":"12.6.69","13":"9.23.30","14":"6.5.10"}},{"v":["Сини Ізраїлеві продовжували чинити зле перед очима Господа, і віддав їх Господь у руки филистимлян на сорок років.","У той час був чоловік з Цори, із племені Данового, на ім’я Маной; дружина його була неплідна і не народжувала.","І явився ангел Господній дружині і сказав їй: ось, ти неплідна і не народжуєш; але зачнеш, і народиш сина;","отже, бережися, не пий вина і сикера, і не їж нічого нечистого;","бо ось, ти зачнеш і народиш сина, і бритва не торкнеться голови його, тому що від самої утроби немовля це буде назореєм Божим, і він почне спасати Ізраїля від руки филистимлян.","Дружина прийшла і сказала чоловіку своєму: чоловік Божий приходив до мене, вигляд якого, як вигляд ангела Божого, дуже величний; я не запитала його, звідки він, і він не сказав мені імені свого;","він сказав мені: «ось, ти зачнеш і народиш сина; отже, не пий вина і сикера і не їж нічого нечистого, бо немовля від самої утроби до смерти своєї буде назореєм Божим».","Маной помолився Господу і сказав: Господи! нехай прийде знову до нас чоловік Божий, якого посилав Ти, і навчить нас, що нам робити з дитиною, яка має народитися.","І почув Бог голос Маноя, і ангел Божий знову прийшов до дружини, коли вона була на полі, і Маноя, чоловіка її, не було з нею.","Дружина негайно побігла і сповістила чоловіка свого і сказала йому: ось, явився мені чоловік, який приходив до мене тоді.","Маной встав і пішов з дружиною своєю, і прийшов до того чоловіка і сказав йому: чи ти той чоловік, який говорив із цією жінкою? [Ангел] сказав: я.","І сказав Маной: отже, якщо сповниться слово твоє, як нам поводитися з дитиною цією і що робити з нею?","Ангел Господній сказав Маною: нехай він остерігається усього, про що я сказав дружині;","нехай не їсть нічого, що вирощує виноградна лоза; нехай не п’є вина і сикера і не їсть нічого нечистого і дотримує всього, що я наказав їй.","І сказав Маной ангелу Господньому: дозволь затримати тебе, доки ми приготуємо для тебе козеня.","Ангел Господній сказав Маною: хоча б ти й затримав мене, але я не буду їсти хліба твого; якщо ж хочеш звершити всепалення Господу, то принеси його. Маной же не знав, що це ангел Господній.","І сказав Маной ангелу Господньому: як твоє ім’я? щоб нам прославити тебе, коли сповниться слово твоє.","Ангел Господній сказав йому: для чого ти запитуєш про ім’я моє? воно чудне.","І взяв Маной козеня і хлібне приношення і приніс Господу на камені. І зробив Він чудо, яке бачили Маной і дружина його.","Коли полум’я стало підніматися від жертовника до неба, ангел Господній піднявся в полум’ї жертовника. Бачачи це, Маной і дружина його впали лицем на землю.","І невидимим став ангел Господній Маною і дружині його. Тоді Маной зрозумів, що це ангел Господній.","І сказав Маной дружині своїй: мабуть, ми помремо, тому що бачили ми Бога.","Дружина його сказала йому: якби Господь хотів умертвити нас, то не прийняв би від наших рук всепалення і хлібне приношення, і не показав би нам усього того, і тепер не відкрив би нам цього.","І народила дружина сина, і нарекла ім’я йому: Самсон. І росла дитина, і благословляв її Господь.","І почав Дух Господній діяти в ній у стані Дановому, між Цорою й Естаолом."],"x":{"1":"6.2.11|6.3.7:12","2":"5.15.33|6.16.31","3":"6.2.1|0.18.10","4":"3.6.3-4","5":"3.6.5","6":"52.1.12","8":"0.25.21","14":"3.6.3|52.1.15","15":"6.6.18","17":"0.32.29","18":"31.9.6|31.45.15","20":"50.17.6|52.1.12","22":"1.19.21|4.5.24-26|50.28.8","24":"75.11.32","25":"8.16.13|50.4.1|52.4.1"}},{"v":["І пішов Самсон у Фимнафу і побачив у Фимнафі жінку з дочок филистимських [і вона сподобалася йому].","Він пішов і оголосив батькові своєму і матері своїй і сказав: я бачив у Фимнафі жінку з дочок филистимських; візьміть її мені за дружину.","Батько і мати його сказали йому: хіба немає жінок між дочками братів твоїх і в усьому народі моєму, що ти йдеш узяти дружину у филистимлян необрізаних? І сказав Самсон батькові своєму: її візьми мені, тому що вона мені сподобалася.","Батько його і мати його не знали, що це від Господа, і що він шукає випадку помститися филистимлянам. А в той час филистимляни панували над Ізраїлем.","І пішов Самсон з батьком своїм і з матір’ю своєю у Фимнафу, і коли підходили до виноградників фимнафських, ось, молодий лев, рикаючи, йде назустріч йому.","І зійшов на нього Дух Господній, і він роздер лева, як козеня; а в руці в нього нічого не було. І не сказав батькові своєму і матері своїй, що він зробив.","І прийшов і поговорив з жінкою, і вона сподобалася Самсону.","Через кілька днів знову пішов він, щоб узяти її, і зайшов подивитися на труп лева, і ось, рій бджіл у трупі лев’ячому і мед.","Він узяв його в руки свої і пішов, і їв дорогою; і коли прийшов до батька свого і матері своєї, дав і їм, і вони їли; але не сказав їм, що з лев’ячого трупа взяв мед цей.","І прийшов батько його до жінки, і зробив там Самсон [семиденний] бенкет, як зазвичай роблять наречені.","І коли побачили його там, вибрали тридцять шлюбних друзів, які були б при ньому.","І сказав їм Самсон: загадаю я вам загадку; якщо ви відгадаєте мені її за сім днів бенкету і відгадаєте правильно, то я дам вам тридцять синдонів* і тридцять змін одягу;","якщо ж не зможете відгадати мені, то ви дайте мені тридцять синдонів і тридцять змін одягу. Вони сказали йому: загадай загадку твою, послухаємо.","І сказав їм: з того, що поїдає, вийшло те, що їдять, і з сильного вийшло солодке. І не могли відгадати загадки за три дні.","В сьомий день сказали вони дружині Самсоновій: умов чоловіка твого, щоб він розгадав нам загадку; інакше спалимо вогнем тебе і дім батька твого; хіба ви покликали нас, щоб обібрати нас?","І плакала дружина Самсонова перед ним і говорила: ти ненавидиш мене і не любиш; ти загадав загадку синам народу мого, а мені не розгадаєш її. Він сказав їй: батькові моєму і матері моїй не розгадав її; і чи тобі розгадаю?","І плакала вона перед ним сім днів, у які продовжувався в них бенкет. Нарешті в сьомий день розгадав їй, бо вона наполегливо просила його. А вона розгадала загадку синам народу свого.","І в сьомий день до заходу сонця сказали йому громадяни: що солодше за мед, і що сильніше за лева! Він сказав їм: якби ви не орали на моїй телиці, то не відгадали б моєї загадки.","І зійшов на нього Дух Господній, і пішов він в Аскалон, і, убивши там тридцять чоловік, зняв з них одяг, і віддав зміну одягу їхнього тим, що розгадали загадку. І запалав гнів його, і пішов він у дім батька свого.","А дружина Самсонова вийшла за шлюбного друга його, який був при ньому другом."],"x":{"3":"1.34.16|4.7.3","6":"6.6.34|8.16.13|75.11.32","12":"10.10.1","15":"6.16.5","17":"6.16.16","19":"6.1.18|9.1.20"},"n":{"12":["Сорочка з тонкого полотна."]}},{"v":["Через кілька днів, під час жнив пшениці, прийшов Самсон побачитися з дружиною своєю, принісши з собою козеня; і коли сказав: «увійду до дружини моєї в спальню», батько її не дав йому ввійти.","І сказав батько її: я подумав, що ти зненавидів її, і я віддав її другові твоєму; ось, менша сестра красивіша за неї; нехай вона буде тобі замість неї.","Але Самсон сказав їм: тепер я буду правим перед филистимлянами, якщо зроблю їм зло.","І пішов Самсон, і впіймав триста лисиць, і взяв смолоскипи, і зв’язав хвіст із хвостом, і прив’язав по смолоскипу між двома хвостами;","і запалив смолоскипи, і пустив їх на жниво филистимське, і випалив і копиці і нежатий хліб, і виноградні сади й оливкові.","І говорили филистимляни: хто це зробив? І сказали: Самсон, зять фимнафянина, бо цей узяв дружину його і віддав другові його. І пішли филистимляни і спалили вогнем її і [дім] батька її.","Самсон сказав їм: хоча ви зробили це, але я помщуся вам самим і тоді тільки заспокоюсь.","І перебив він їм гомілки і стегна, і пішов і засів в ущелині скелі Етама.","І пішли филистимляни, і розташувалися станом в Іудеї, і розтягнулися до Лехи.","І сказали жителі Іудеї: за що ви вийшли проти нас? Вони сказали: ми прийшли зв’язати Самсона, щоб учинити з ним, як він учинив з нами.","І пішли три тисячі чоловік з Іудеї до ущелини скелі Етама і сказали Самсону: хіба ти не знаєш, що филистимляни панують над нами? що це ти зробив нам? Він сказав їм: Як вони зі мною вчинили, так і я вчинив з ними.","І сказали йому: ми прийшли зв’язати тебе, щоб віддати тебе в руки филистимлянам. І сказав їм Самсон: покляніться мені, що ви не уб’єте мене.","І сказали йому: ні, ми тільки зв’яжемо тебе і віддамо тебе в руки їхні, а умертвити не умертвимо. І зв’язали його двома новими мотузками і повели його з ущелини.","Коли він підійшов до Леха, филистимляни з криком зустріли його. І зійшов на нього Дух Господній, і мотузки, що були на руках його, зробилися, як перегорілий льон, і упали пута з рук його.","Знайшов він свіжу ослячу щелепу і, простягнувши руку свою, взяв її, і вбив нею тисячу чоловік.","І сказав Самсон: щелепою ослячою юрбу, дві юрби, щелепою ослячою убив я тисячу чоловік.","Сказавши це, кинув щелепу з рук своїх і назвав те місце: Рамаф-Лехи*.","І відчув сильну спрагу і воззвав до Господа і сказав: Ти зробив рукою раба Твого велике спасіння це; а тепер помру я від спраги, і потраплю в руки необрізаних.","І розверз Бог щілину в Леху, і потекла з неї вода. Він напився, і повернувся дух його, і він ожив; від того і наречено ім’я місцю цьому: «Джерело того, хто взиває», яке у Леху до цього дня.","І був він суддею Ізраїля в дні филистимлян двадцять років."],"x":{"3":"6.14.4","6":"6.6.29","14":"6.6.34|6.11.29|6.14.6","19":"8.30.12","20":"6.16.31"},"n":{"17":["Кинута щелепа."]}},{"v":["Прийшов одного разу Самсон у Газу і, побачивши там блудницю, увійшов до неї.","Жителям Гази сказали: Самсон прийшов сюди. І ходили вони навкруги, і підстерігали його всю ніч біля воріт міста, і ховалися всю ніч, говорячи: до світла ранкового почекаємо, і вб’ємо його.","А Самсон спав до півночі; опівночі ж, уставши, схопив двері міських воріт з обома одвірками, підняв їх разом із запором, поклав на плечі свої і відніс їх на вершину гори, яка на шляху до Хеврона, [і поклав їх там].","Після того полюбив він одну жінку, яка жила в долині Сорек; ім’я їй Даліда.","До неї прийшли власники филистимські і говорять їй: умов його, і вивідай, у чому велика сила його і як нам здолати його, щоб зв’язати його й упокорити його; а ми дамо тобі за те кожен тисячу сто сиклів срібла.","І сказала Даліда Самсону: скажи мені, в чому велика сила твоя і чим зв’язати тебе, щоб упокорити тебе?","Самсон сказав їй: якщо зв’яжуть мене сімома сирими тятивами, які не висушені, то я зроблюся безсилим і буду як і інші люди.","І принесли їй власники филистимські сім сирих тятив, які не висохли, і вона зв’язала його ними.","[Тим часом один таємно сидів у неї в спальні.] І сказала йому: Самсоне! Филистимляни йдуть на тебе. Він розірвав тятиви, як розривають нитку з клоччя, коли перепалить її вогонь. І не пізнана сила його.","І сказала Даліда Самсону: ось, ти обманув мене і говорив мені неправду; скажи ж тепер мені, чим зв’язати тебе?","Він сказав їй: якщо зв’яжуть мене новими мотузками, що не були в ділі, то я зроблюся безсилим і буду, як інші люди.","Даліда взяла нові мотузки і зв’язала його і сказала йому: Самсоне! Филистимляни йдуть на тебе. [Тим часом один таємно сидів у спальні.] І зірвав він їх з рук своїх, як нитки.","І сказала Даліда Самсону: все ти обманюєш мене і говориш мені неправду; скажи мені, чим би зв’язати тебе? Він сказав їй: якщо ти увіткнеш сім кіс голови моєї в тканину і приб’єш її цвяхом до ткальної колоди, [то я буду безсилим, як і інші люди].","[І приспала його Даліда на колінах своїх. І коли він заснув, узяла Даліда сім кіс голови його,] і прикріпила їх до колоди, і сказала йому: филистимляни йдуть на тебе, Самсоне! Він пробудився від сну свого і висмикнув ткальну колоду разом із тканиною; [і не пізнана сила його].","І сказала йому [Даліда]: як же ти говориш: «люблю тебе», а серце твоє не зі мною? ось, ти тричі обманув мене, і не сказав мені, в чому велика сила твоя.","І оскільки вона словами своїми тяготила його кожного дня і мучила його, то душі його стало важко до смерти.","І він відкрив їй усе серце своє, і сказав їй: бритва не торкалася голови моєї, тому що я назорей Божий від утроби матері моєї; якщо ж обстригти мене, то відступить від мене сила моя; я зроблюся слабким і буду, як інші люди.","Даліда, бачачи, що він відкрив їй усе серце своє, послала і покликала власників филистимських, сказавши їм: йдіть тепер; він відкрив мені все серце своє. І прийшли до неї власники филистимські і принесли срібло в руках своїх.","І приспала його [Даліда] на колінах своїх, і покликала чоловіка, і веліла йому обстригти сім кіс голови його. І почав він слабнути, і відступила від нього сила його.","Вона сказала: филистимляни йдуть на тебе, Самсоне! Він пробудився від сну свого, і сказав: піду, як і раніше, і визволюся. А не знав, що Господь відступив від нього.","Филистимляни взяли його і викололи йому очі, привели його в Газу й скували його двома мідними ланцюгами, і він молов у в’язниці.","Тим часом волосся на голові його почало рости, де воно було обстрижене.","Власники филистимські зібралися, щоб принести велику жертву Дагону, богу своєму, і повеселитися, і сказали: бог наш віддав Самсона, ворога нашого, в руки наші.","Також і народ, бачачи його, прославляв бога свого, говорячи: бог наш видав у руки наші ворога нашого, і спустошувача землі нашої, який убив багатьох з нас.","І коли розвеселилося серце їхнє, сказали: покличте Самсона [з в’язниці], нехай він забавляє нас. І покликали Самсона з в’язниці, і він забавляв їх, [і били його по обличчю] і поставили його між стовпами.","І сказав Самсон юнакові, який водив його за руку: підведи мене, щоб обмацати мені стовпи, на яких утверджений дім, і притулитися до них. [Юнак так і зробив.]","Дім же був повен чоловіків і жінок; там були всі власники филистимські, і на покрівлі було до трьох тисяч чоловіків і жінок, які дивилися на Самсона, що забавляв їх.","І воззвав Самсон до Господа і сказав: Господи Боже! згадай мене і зміцни мене тільки тепер, о Боже! щоб мені за один раз помститися филистимлянам за два ока мої.","І зрушив Самсон з місця два середніх стовпи, на яких був утверджений дім, упершись у них, в один правою рукою своєю, а в другий лівою.","І сказав Самсон: помри, душе моя, з филистимлянами! Й уперся з усією силою, й обвалився дім на власників і на весь народ, що був у ньому. І було померлих, яких умертвив [Самсон] у смерті своїй, більше, ніж він умертвив за життя своє.","І прийшли брати його і весь дім батька його, і взяли його, і пішли і поховали його між Цорою й Естаолом, у гробі Маноя, батька його. Він був суддею Ізраїля двадцять років. [Після Самсона постав Емегар, син Енана, й убив з іноплемінників шістсот чоловік, крім худоби. І він спас Ізраїля.]"],"x":{"1":"5.15.47","2":"52.20.20","3":"75.11.34","4":"4.1.24","5":"6.14.15|6.17.2","9":"6.15.14","17":"6.13.5","19":"3.6.5","20":"8.28.15","21":"32.39.7|31.47.2","23":"8.5.2","25":"50.27.28:30","28":"19.13.4|75.11.34","30":"10.19.4|75.2.14","31":"6.13.2|6.15.20"}},{"v":["Був хтось на горі Єфремовій, на ім’я Миха.","Він сказав матері своїй: тисяча сто сиклів срібла, які в тебе взяті і за які ти при мені проголосила прокляття, це срібло в мене, я взяв його. Мати його сказала: благословенний син мій у Господа!","І повернув він матері своїй тисячу сто сиклів срібла. І сказала мати його: це срібло я від себе присвятила Господу для [тебе,] сина мого, щоб зробити з нього ідола і відлитого кумира; отже, віддаю це тобі.","Але він повернув срібло матері своїй. Мати його взяла двісті сиклів срібла і віддала їх плавильникові. Він зробив з них ідола і відлитого кумира, який і знаходився в домі Михи.","І був у Михи дім Божий. І зробив він ефод і терафим і посвятив одного із синів своїх, щоб він був у нього священиком.","У ті дні не було царя в Ізраїля; кожен робив те, що йому здавалося справедливим.","Один юнак з Вифлеєма Юдейського, з коліна Іудиного, левит, тоді жив там;","цей чоловік пішов з міста Вифлеєма Юдейського, щоб пожити, де трапиться, і йдучи дорогою, прийшов на гору Єфремову до дому Михи.","І сказав йому Миха: звідки ти йдеш? Він сказав йому: я левит з Вифлеєма Юдейського і йду пожити, де трапиться.","І сказав йому Миха: залишся у мене і будь у мене отцем і священиком; я буду давати тобі по десять сиклів срібла на рік, потрібний одяг і їжу.","Левит пішов до нього і погодився левит залишитися у цієї людини, і був юнак у нього, як один із синів його.","Миха посвятив левита, і цей юнак був у нього священиком і жив у домі Михи.","І сказав Миха: тепер я знаю, що Господь буде мені благодіяти, тому що левит у мене священиком."],"x":{"2":"7.3.10|8.15.13","4":"31.40.19|29.15.9|6.18.17","6":"6.18.1|6.19.1|6.21.25","10":"6.18.4"}},{"v":["У ті дні не було царя в Ізраїля; і в ті дні коліно Данове шукало собі наділ, де б оселитися, тому що до того часу не випало йому повного наділу між колінами Ізраїлевими.","І послали сини Дана від племені свого п’ять чоловік, мужів сильних, з Цори й Естаола, щоб оглянути землю й дізнатися про неї, і сказали їм: підіть, узнайте землю. Вони прийшли на гору Єфремову до дому Михи і ночували там.","Перебуваючи біля дому Михи, впізнали вони голос молодого левита і зайшли туди і запитали його: хто тебе привів сюди? що ти тут робиш і навіщо ти тут?","Він сказав їм: те і те зробив для мене Миха, найняв мене, і я в нього священиком.","Вони сказали йому: запитай Бога, щоб знати нам, чи успішною буде путь наша, в яку ми йдемо.","Священик сказав їм: ідіть з миром; перед Господом путь ваша, в яку ви йдете.","І пішли ті п’ять чоловіків, і прийшли в Лаїс, і побачили народ, який у ньому, що він живе спокійно, за звичаєм сидонян, тихий і безтурботний, і що не було в землі тій, щоб хто кривдив у чому або мав би владу: від сидонян вони жили далеко, і ні з ким не було у них ніякої справи.","І повернулися [ті п’ять чоловік] до братів своїх у Цору й Естаол, і сказали їм брати їхні: з чим ви?","Вони сказали: встанемо і підемо на них; ми бачили землю, вона дуже добра; а ви задумалися: не баріться йти і взяти в спадщину ту землю;","коли підете ви, прийдете до народу безтурботного, і земля та велика; Бог віддає її в руки ваші; це таке місце, де немає ні в чому нестатку, що виникає від землі.","І вирушили звідти з коліна Данового, з Цори й Естаола, шістсот чоловіків, оперезавшись військовою зброєю.","Вони пішли і стали станом у Кириаф-Іаримі, в Юдеї. Тому і називають те місце станом Дановим до цього дня. Він позаду Кириаф-Іарима.","Звідти вирушили вони на гору Єфремову і прийшли до дому Михи.","І сказали ті п’ять чоловіків, що ходили оглядати землю Лаїс, братам своїм: чи знаєте, що в одному з домів цих є ефод, терафим, ідол і відлитий кумир? отже, подумайте, що зробити.","І зайшли туди, і ввійшли в дім молодого левита, у дім Михи, і вітали його.","А шістсот чоловік із синів Данових, оперезані військовою зброєю, стояли біля воріт.","П’ять же чоловік, які ходили оглядати землю, пішли, увійшли туди, взяли ідола й ефод і терафим і відлитого кумира. Священик стояв біля воріт з тими шістьмастами людьми, оперезаними військовою зброєю.","Коли вони ввійшли в дім Михи і взяли ідола, ефод, терафим і відлитого кумира, священик сказав їм: що ви робите?","Вони сказали йому: мовчи, поклади руку твою на вуста твої й іди з нами і будь у нас отцем і священиком; чи краще тобі бути священиком у домі однієї людини, ніж бути священиком у коліні або в племені Ізраїлевому?","Священик зрадів, взяв ефод, терафим і ідола [і відлитого кумира], і пішов з народом.","Вони обернулися і пішли, і відпустили дітей, худобу і майно вперед.","Коли вони віддалилися від дому Михи, [Миха і] мешканці домів, сусідніх з домом Михи, зібралися і погналися за синами Дана,","і кричали синам Дана. [Сини Данові] обернулися і сказали Миху: чого тобі, що ти так кричиш?","[Миха] сказав: ви взяли богів моїх, яких я зробив, і священика, і пішли; чого ще більше? як же ви говорите: чого тобі?","Сини Данові сказали йому: мовчи, щоб ми не чули голосу твого; інакше деякі з нас, розгнівавшись, нападуть на вас, і ти погубиш себе і родину твою.","І пішли сини Данові шляхом своїм; Миха ж, бачачи, що вони сильніші за нього, пішов назад і повернувся в дім свій.","А [сини Данові] узяли те, що зробив Миха, і священика, який був у нього, і пішли в Лаїс, проти народу спокійного і безтурботного, і знищили його мечем, а місто спалили вогнем.","Нікому було допомогти, тому що він був віддалений від Сидона і ні з ким не мав справи. [Місто це] знаходилося в долині, що поблизу Беф-Рехова. І побудували знову місто й оселилися в ньому,","і нарекли ім’я місту: Дан, за ім’ям батька свого Дана, сина Ізраїлевого; а раніше ім’я місту тому було: Лаїс.","І поставили в себе сини Данові ідола; Іонафан же, син Гирсона, сина Манассії, сам і сини його були священиками в коліні Дановім до дня переселення жителів тієї землі;","і мали у себе ідола, зробленого Михою, весь той час, коли дім Божий знаходився в Силомі."],"x":{"1":"6.1.34|6.17.6|5.19.40","2":"5.19.47|6.17.1","4":"6.17.10","5":"8.23.10","7":"5.19.47","11":"6.13.25","12":"5.15.60|32.26.20","14":"31.10.30|6.17.4-5","19":"6.17.10","24":"0.31.30","28":"9.10.6","29":"0.14.14|5.19.47","30":"0.49.17|1.32.1|10.12.29","31":"32.17.12"}},{"v":["У ті дні, коли не було царя в Ізраїля, жив один левит на схилі гори Єфремової. Він узяв собі наложницю з Вифлеєма Юдейського.","Наложниця його посварилася з ним і пішла від нього в дім батька свого у Вифлеєм Юдейський і була там чотири місяці.","Чоловік її встав і пішов за нею, щоб поговорити до серця її і повернути її до себе. З ним був слуга його і пара ослів. Вона ввела його в дім батька свого.","Батько цієї молодої жінки, побачивши його, з радістю зустрів його, і затримав його тесть його, батько молодої жінки. І пробув він у нього три дні; вони їли і пили і ночували там.","На четвертий день встали вони рано, і він встав, щоб іти. І сказав батько молодої жінки зятеві своєму: підкріпи серце твоє шматком хліба, і потім підете.","Вони залишилися, і обоє разом їли і пили. І сказав батько молодої жінки чоловікові тому: залишися ще на ніч, і нехай повеселиться серце твоє.","Чоловік той устав, було, щоб іти, але тесть його ублагав його, і він знову ночував там.","На п’ятий день устав він вранці, щоб іти. І сказав батько молодої жінки тієї: підкріпи серце твоє [хлібом], і забаріться, доки схилиться день. І їли обоє вони [і пили].","І встав той чоловік, щоб іти, сам він, наложниця його і слуга його. І сказав йому тесть його, батько молодої жінки: ось, день схилився до вечора, ночуйте, будь ласка; ось, день незабаром закінчиться, ночуй тут, нехай повеселиться серце твоє; завтра рано встанете в дорогу вашу, і підеш у дім твій.","Але чоловік не погодився ночувати, встав і пішов; і прийшов до Ієвуса, що нині Єрусалим; з ним пара нав’ючених ослів і наложниця його з ним.","Коли вони були біля Ієвуса, день уже дуже схилився. І сказав слуга господарю своєму: зайдемо в це місто ієвусеїв і заночуємо в ньому.","Господар його сказав йому: ні, не підемо в місто іноплемінників, які не з синів Ізраїлевих, але дійдемо до Гиви.","І сказав слузі своєму: дійдемо до одного з цих місць і заночуємо в Гиві або в Рамі.","І пішли, і йшли, і зайшло сонце біля Гиви Веніамінової.","І повернули вони туди, щоб піти заночувати в Гиві. І прийшов він і сів на вулиці в місті; але ніхто не запрошував їх у дім для ночівлі.","І ось, іде один старий з роботи своєї з поля ввечері; він був родом з гори Єфремової і жив у Гиві. Жителі ж місця цього були синами Веніаміновими.","Він, піднявши очі свої, побачив перехожого на вулиці міській. І сказав старий: куди йдеш? і звідки ти прийшов?","Він сказав йому: ми йдемо з Вифлеєма Юдейського на гору Єфремову, звідки я; я ходив у Вифлеєм Юдейський, а тепер іду до дому Господа; і ніхто не запрошує мене в дім;","у нас є і солома і корм для ослів наших; також хліб і вино для мене і для раби твоєї і для цього слуги є в рабів твоїх; ні у чому немає нестатку.","Старий сказав йому: будь спокійним: весь нестаток твій на мені, тільки не ночуй на вулиці.","І ввів його в дім свій і дав корм ослам [його], а самі вони обмили ноги свої і їли і пили.","Тоді як вони розвеселили серця свої, ось, жителі міста, люди розпусні, оточили дім, стукали в двері і говорили старому, господареві дому: виведи чоловіка, який увійшов у дім твій, ми пізнаємо його.","Господар дому вийшов до них і сказав їм: ні, брати мої, не чиніть зла, коли чоловік цей ввійшов у дім мій, не робіть цього безумства;","ось у мене дочка дівчина, і в нього наложниця, виведу я їх, смиріть їх і робіть з ними, що вам завгодно; а з чоловіком цим не робіть цього безумства.","Але вони не хотіли слухати його. Тоді чоловік узяв свою наложницю і вивів до них на вулицю. Вони пізнали її, і глумилися над нею всю ніч до ранку. І відпустили її з появою зорі.","І прийшла жінка перед появою зорі, і впала біля дверей дому тієї людини, у якої був господар її, і лежала до світла.","Господар її встав зранку, відчинив двері дому і вийшов, щоб іти в дорогу свою: і ось, наложниця його лежить біля дверей дому, і руки її на порозі.","Він сказав їй: вставай, підемо. Але відповіді не було, [тому що вона померла]. Він поклав її на осла, встав і пішов у своє місце.","Прийшовши в дім свій, він узяв ніж і, взявши наложницю свою, розрізав її за членами її на дванадцять частин і послав в усі краї Ізраїлеві.","Всякий, хто бачив це, говорив: не бувало і не бачено було подібного до цього від дня виходу синів Ізраїлевих із землі Єгипетської до цього дня. [Посланим же від себе людям він дав наказ і сказав: так говоріть усьому Ізраїлю: чи бувало коли подібне до цього?] Зверніть увагу на це, порадьтеся і скажіть."],"x":{"1":"6.17.7|6.18.1|0.35.19","10":"0.10.16|5.15.63|9.5.6","12":"66.2.12","13":"9.5.25","15":"6.20.4","16":"0.35.18|6.3.15|9.16.11","20":"6.6.23|54.16.15|75.13.2","21":"0.18.4","22":"0.19.4-5|38.9.9","23":"0.19.7|0.34.7","24":"0.19.8","30":"6.18.14"}},{"v":["І вийшли всі сини Ізраїлеві, і зібралася вся громада, як одна людина, від Дана до Вирсавії, і земля Галаадська перед Господом у Массифу.","І зібралися [перед Господом] начальники всього народу, всі коліна Ізраїлеві, на зібрання народу Божого, чотириста тисяч піших, що оголюють меч.","І сини Веніамінові почули, що сини Ізраїлеві прийшли в Массифу. І сказали сини Ізраїлеві: скажіть, як відбувалося це зло?","Левит, чоловік тієї убитої жінки, відповів і сказав: я з наложницею моєю прийшов ночувати в Гиву Веніамінову;","і повстали на мене жителі Гиви й оточили через мене дім уночі; мене мали намір убити, і наложницю мою замучили, [наглумившись над нею,] так, що вона померла;","я взяв наложницю мою, розрізав її і послав її в усі області володіння Ізраїлевого, тому що вони зробили беззаконня і соромітну справу в Ізраїлі;","ось усі ви, сини Ізраїлеві, розгляньте цю справу і вирішіть тут.","І повстав весь народ, як одна людина, і сказав: не підемо ніхто в намет свій і не повернемося ніхто в дім свій;","і ось що ми зробимо нині з Гивою: [підемо] на неї за жеребом;","і візьмемо по десять чоловік зі ста від усіх колін Ізраїлевих, по сто від тисячі і по тисячі від десяти тисяч, щоб вони принесли харчові припаси для народу, який піде проти Гиви Веніамінової, покарати її за соромітну справу, яку вона зробила в Ізраїлі.","І зібралися всі ізраїльтяни проти міста одностайно, як одна людина.","І послали коліна Ізраїлеві в усе коліно Веніамінове сказати: яка це мерзенна справа зроблена у вас!","Видайте розбещених тих людей, що у Гиві; ми умертвимо їх і викорінимо зло з Ізраїля. Але сини Веніамінові не хотіли послухати голосу братів своїх, синів Ізраїлевих;","а зібралися сини Веніамінові з міст у Гиву, щоб піти війною проти синів Ізраїлевих.","І налічилося у той день синів Веніамінових, тих, що зібралися з міст, двадцять шість тисяч чоловік, що оголюють меч; крім того, з жителів Гиви нараховано сімсот добірних;","з усього народу цього було сімсот чоловік добірних, які були лівші, і всі ці, кидаючи з пращ камені у волосину, не кидали мимо.","Ізраїльтян же, крім синів Веніамінових, нарахували чотириста тисяч чоловік, які оголюють меч; усі вони були здатні до війни.","І встали і пішли в дім Божий, і запитали Бога і сказали сини Ізраїлеві: хто з нас першим піде на війну із синами Веніаміна? І сказав Господь: Іуда [піде] попереду.","І встали сини Ізраїлеві вранці і розташувалися станом біля Гиви;","і виступили ізраїльтяни на війну проти Веніаміна, і стали сини Ізраїлеві в бойовий порядок біля Гиви.","І вийшли сини Веніамінові з Гиви і поклали в той день двадцять дві тисячі ізраїльтян на землю.","Але народ Ізраїльський підбадьорився, і знову стали в бойовий порядок на тім місці, де стояли минулого дня.","І пішли сини Ізраїлеві, і плакали перед Господом до вечора, і запитували Господа: чи вступати мені ще у війну з синами Веніаміна, брата мого? Господь сказав: ідіть проти нього.","І підступили сини Ізраїлеві до синів Веніаміна на другий день.","Веніамін вийшов проти них з Гиви на другий день, і ще поклали на землю із синів Ізраїлевих вісімнадцять тисяч чоловік, що оголюють меч.","Тоді всі сини Ізраїлеві і весь народ пішли і прийшли в дім Божий і, сидячи там, плакали перед Господом, і постились у той день до вечора, і принесли всепалення і мирні жертви перед Господом.","І запитували сини Ізраїлеві Господа [у той час ковчег завіту Божого знаходився там,","і Финеєс, син Єлеазара, сина Ааронового, стояв перед ним]: чи виходити мені ще на війну із синами Веніаміна, брата мого, чи ні? Господь сказав: ідіть; Я завтра віддам його в руки ваші.","І поставив Ізраїль засідку навколо Гиви.","І пішли сини Ізраїлеві на синів Веніаміна на третій день і стали в бойовий порядок перед Гивою, як раніше.","Сини Веніамінові виступили проти народу і віддалилися від міста, і почали, як раніше, вбивати з народу на дорогах, з яких одна йде до Вефиля, а друга до Гиви полем, і вбили до тридцяти чоловік з ізраїльтян.","І сказали сини Веніамінові: вони падають перед нами, як і раніше. А сини Ізраїлеві сказали: побіжимо від них і відволічемо їх від міста на дороги. [І зробили так.]","І всі ізраїльтяни встали зі свого місця і вишикувалися у Ваал-Фамарі. І засідка Ізраїлева кинулася зі свого місця із західного боку Гиви.","І прийшли до Гиви десять тисяч чоловік добірних з усього Ізраїлю, і почався жорстокий бій; але сини Веніаміна не знали, що має бути їм біда.","І вразив Господь Веніаміна перед ізраїльтянами, і поклали в той день ізраїльтяни з синів Веніаміна двадцять п’ять тисяч сто чоловік, які оголювали меч.","Коли сини Веніаміна побачили, що вони розбиті, тоді ізраїльтяни поступилися місцем синам Веніаміна, бо сподівалися на засідку, яку вони поставили біля Гиви.","Засідка ж поспішила і кинулася до Гиви, і вступила і вразила все місто мечем.","Ізраїльтяни поставили із засідкою умовним знаком до нападу дим, що піднімається з міста.","Отже, коли ізраїльтяни відступили з місця бою, і Веніамін почав уражати й убив ізраїльтян до тридцяти чоловік і говорив: «знову падають вони перед нами, як і в попередньому бою»,","тоді почав підніматися з міста дим стовпом. Веніамін озирнувся назад, і ось, дим від усього міста піднімається до неба.","Ізраїльтяни повернулися, а Веніамін злякався, тому що побачив, що прийшла його загибель.","І побігли вони від ізраїльтян по дорозі до пустелі; але військо переслідувало їх, і ті, що виходили з міст, убивали їх там;","оточили Веніаміна, і переслідували його до Менухи й уражали до самого східного боку Гиви.","І упало з синів Веніаміна вісімнадцять тисяч чоловік, людей сильних.","[Ті, що залишилися,] повернулися і побігли до пустелі, до скелі Риммона, й убили ще [ізраїльтяни] на дорогах п’ять тисяч чоловік; і гналися за ними до Гидома і ще вбили з них дві тисячі чоловік.","Усіх же синів Веніамінових, які упали в той день, було двадцять п’ять тисяч чоловік, які оголювали меч, і всі вони були людьми сильними.","І повернулися [ті, що залишилися,] і втекли в пустелю, до скелі Риммона, шістсот чоловік, і залишалися там у кам’яній горі Риммоні чотири місяці.","Ізраїльтяни ж знову пішли до синів Веніамінових і вразили їх мечем, і людей у місті, і худобу, й усе, що тільки зустрічалося [у всіх містах], і все, що знаходилося на дорозі міста, спалили вогнем."],"x":{"1":"38.10.9","4":"6.19.15","6":"6.19.29|0.34.7|32.29.23","7":"6.19.30","13":"6.19.22|38.9.9","16":"6.3.15","18":"6.1.1-2|6.19.18","29":"6.20.37|8.15.5","35":"1.15.3","40":"5.8.20","47":"6.21.13"}},{"v":["І поклялися ізраїльтяни в Массифі, говорячи: ніхто з нас не віддасть дочки своєї синам Веніаміна заміж.","І прийшов народ у дім Божий, і сиділи там до вечора перед Богом, і підняли голосне волання, і сильно плакали,","і сказали: Господи, Боже Ізраїлів! для чого трапилося це в Ізраїлі, що не стало тепер у Ізраїля одного коліна?","На другий день устав народ вранці, і спорудили там жертовник, і принесли всепалення і мирні жертви.","І сказали сини Ізраїлеві: хто не приходив на зібрання перед Господом з усіх колін Ізраїлевих? Бо велике прокляття було проголошено на тих, які не прийшли перед Господом у Массифу, і було сказано, що ті віддані будуть на смерть.","І зласкавилися сини Ізраїлеві над Веніаміном, братом своїм, і сказали: нині відсічене одне коліно від Ізраїля;","як вчинити нам з тими, що залишилися з них, стосовно дружин, коли ми поклялися Господом не давати їм дружин з дочок наших?","І сказали: чи немає кого з колін Ізраїлевих, хто не приходив перед Господом у Массифу? І виявилося, що з Іависа галаадського ніхто не приходив перед Господом у стан на зібрання.","І оглянули народ, і ось, не було там жодного з жителів Іависа галаадського.","І послала туди громада дванадцять тисяч чоловік, чоловіків сильних, і дали їм наказ, говорячи: йдіть і знищіть жителів Іависа галаадського мечем, і жінок і дітей;","і ось що зробіть: усякого чоловіка і всяку жінку, що пізнала ложе чоловікове, піддайте закляттю, [а дівчат залишайте живими. І зробили так].","І знайшли вони між жителями Іависа галаадського чотириста дівчат, які не пізнали ложа чоловікового, і привели їх у стан у Силом, що в землі Ханаанській.","І послала вся громада переговорити із синами Веніаміна, які були в скелі Риммоні, і оголосила їм мир.","Тоді повернулися сини Веніаміна [до ізраїльтян], і дали їм [ізраїльтяни] дружин, яких залишили в живих з жінок Іависа галаадського; але виявилося, що цього було недостатньо.","Народ же жалкував за Веніаміном, що Господь не зберіг цілости колін Ізраїлевих.","І сказали старійшини громади: що нам робити з тими, що залишилися, стосовно дружин, бо знищені жінки у Веніаміна?","І сказали: спадкоємна земля нехай залишається синам Веніаміна, які вціліли, щоб не зникло коліно від Ізраїля;","але ми не можемо дати їм дружин з дочок наших; тому що сини Ізраїлеві поклялися, говорячи: проклятий, хто дасть дружину Веніаміну.","І сказали: ось, щороку буває свято Господнє у Силомі, що на північ від Вефиля і на схід від дороги, яка веде від Вефиля в Сихем, і на південь від Левони.","І наказали синам Веніаміна і сказали: підіть і засядьте у виноградниках,","і дивіться, коли вийдуть дівчата силомські танцювати в хороводах, тоді вийдіть з виноградників і захопіть собі кожен дружину з дівчат силомських і йдіть у землю Веніамінову;","і коли прийдуть батьки їхні, або брати їхні зі скаргою до нас, ми скажемо їм: простіть нас за них, бо ми не взяли для кожного з них дружини на війні, і ви не дали їм; тепер ви винні.","Сини Веніаміна так і зробили, і взяли дружин за числом своїм з тих, що були у хороводі, яких вони викрали, і пішли і повернулися в наділ свій, і побудували міста і стали жити в них.","У той же час ізраїльтяни розійшлися звідти кожен у коліно своє й у плем’я своє, і пішли звідти кожен у наділ свій.","У ті дні не було царя в Ізраїлі; кожен робив те, що йому здавалося справедливим."],"x":{"1":"6.20.1","3":"8.9.21","4":"10.8.63","7":"6.21.1","8":"8.11.1","11":"3.31.17","21":"1.15.20|8.18.6|6.21.12","25":"6.17.6|6.18.1"}}];
export default C;
